const SLUG_TO_VIEW = Object.fromEntries(
  Object.entries(VIEW_PAGES).map(([mod, pages]) => [mod, Object.fromEntries(pages.map((p) => [p.slug, p.viewId]))])
)

export function viewPageFor(moduleId, viewId) {
  return VIEW_PAGES[moduleId]?.find((p) => p.viewId === viewId) ?? null
}

export function viewIdForSlug(moduleId, slug) {
  return SLUG_TO_VIEW[moduleId]?.[slug] ?? null
}
